const maxListRows = 8

func screen(a *App) []string { return strings.Split(ansi.Strip(a.View()), "\n") }

// filetIndex returns the line of the list's bottom rule, or -1.
func filetIndex(lines []string) int {
	for i, l := range lines {
		if strings.HasPrefix(l, "├─") {
			return i
		}
	}
	return -1
}

